#include <iostream>
#include <string>

struct Sinhvien {
    std::string hoten;
    float diem;
    Sinhvien* tiep{nullptr};
};

void chenDau(Sinhvien*& head, const std::string& ten, float diem) {
    Sinhvien* moi = new Sinhvien{ten, diem, head};
    head = moi;
}

void inDanhSach(const Sinhvien* head) {
    const Sinhvien* p = head;
    while (p != nullptr) {
        std::cout << p->hoten << " (" << p->diem << ") -> ";
        p = p->tiep;
    }
    std::cout << "NULL\n";
}

void xoaSau(Sinhvien* p) {
    if (p != nullptr && p->tiep != nullptr) {
        Sinhvien* x = p->tiep;
        p->tiep = x->tiep;
        delete x;
    }
}

void giaiPhong(Sinhvien*& head) {
    while (head != nullptr) {
        Sinhvien* temp = head;
        head = head->tiep;
        delete temp;
    }
}

int main() {
    Sinhvien* head = nullptr;
    chenDau(head, "PHT", 4.0f);
    chenDau(head, "TTB", 7.5f);
    chenDau(head, "NVA", 9.0f);

    std::cout << "Danh sach ban dau:\n";
    inDanhSach(head);

    // Chen MOI giua NVA va TTB
    Sinhvien* moi = new Sinhvien{"MOI", 10.0f, head->tiep};
    head->tiep = moi;
    std::cout << "Sau khi chen MOI:\n";
    inDanhSach(head);

    // Xoa MOI (phan tu sau head)
    xoaSau(head);
    std::cout << "Sau khi xoa MOI:\n";
    inDanhSach(head);

    giaiPhong(head);
    return 0;
}
